123	/****************************************************************************
124	 * Name: sdmmc_mount_task
125	 *
126	 * Description:
127	 *   Background task that initializes the SDMMC slot and mounts the SD card
128	 *   with retries.  Card probing plus the mount retry loop can take several
129	 *   seconds (worst case when no card is inserted).  Running this
130	 *   synchronously from esp32s3_bringup() delayed NSH and the watch UI,
131	 *   leaving the screen black for that whole time.
132	 *
133	 ****************************************************************************/
134	
135	static int sdmmc_mount_task(int argc, FAR char *argv[])
136	{
137	  int ret;
138	  int mount_retries;
139	  struct stat buf;
140	
141	  /* Create mount point for SD card */
142	
143	  ret = mkdir("/mnt", 0755);
144	  if (ret < 0 && errno != EEXIST)
145	    {
146	      syslog(LOG_ERR, "ERROR: Failed to create /mnt: %d\n", ret);
147	    }
148	
149	  ret = mkdir("/mnt/sd", 0755);
150	  if (ret < 0 && errno != EEXIST)
151	    {
152	      syslog(LOG_ERR, "ERROR: Failed to create /mnt/sd: %d\n", ret);
153	    }
154	
155	  /* SD initialize.
156	   * The TF card slot is wired for SPI (MOSI=GPIO1, SCK=GPIO2, MISO=GPIO3,
157	   * SDCS=GPIO17) but we use native SDMMC 1-bit mode.  The card samples its
158	   * CS/DAT3 line at power-on to decide between SPI and SD mode; drive GPIO17
159	   * high so the card enters SD mode and stays there after a soft reboot.
160	   */
161	
162	  esp32s3_configgpio(17, OUTPUT);
163	  esp32s3_gpiowrite(17, true);
164	  usleep(10000);
165	
166	  syslog(LOG_INFO, "Initializing SDMMC...\n");
167	  ret = board_sdmmc_initialize();
168	  if (ret < 0)
169	    {
170	      syslog(LOG_ERR, "ERROR: Failed to initialize SDMMC: %d\n", ret);
171	    }
172	  else
173	    {
174	      syslog(LOG_INFO, "SDMMC initialized successfully\n");
175	    }
176	
177	  /* Wait for SD card to be ready and try to mount with retries.
178	   * Some cards take longer to become ready after power-on, so we first
179	   * wait for the block device to appear and then retry the mount.
180	   */
181	
182	  syslog(LOG_INFO, "Waiting for SD card...\n");
183	
184	  for (mount_retries = 0; mount_retries < 20; mount_retries++)
185	    {
186	      if (stat("/dev/mmcsd1", &buf) == 0)
187	        {
188	          ret = nx_mount("/dev/mmcsd1", "/mnt/sd", "vfat", 0, NULL);
189	          if (ret == OK)
190	            {
191	              syslog(LOG_INFO, "SD card mounted at /mnt/sd\n");
192	              break;
193	            }
194	
195	          syslog(LOG_ERR, "ERROR: Failed to mount SD card (attempt %d): %d\n",
196	                 mount_retries + 1, ret);
197	        }
198	      else
199	        {
200	          syslog(LOG_INFO, "SD card block device not ready (attempt %d)\n",
201	                 mount_retries + 1);
202	        }
203	
204	      usleep(200000);  /* Wait 200ms before retry */
205	    }
206	
207	  return OK;
208	}
209	#endif /* CONFIG_ESP32S3_SDMMC */
