127	/****************************************************************************
128	 * Name: sdmmc_mount_task
129	 *
130	 * Description:
131	 *   Background task that initializes the SDMMC slot and mounts the SD card
132	 *   with retries.  Card probing plus the mount retry loop can take several
133	 *   seconds (worst case when no card is inserted).  Running this
134	 *   synchronously from esp32s3_bringup() delayed NSH and the watch UI,
135	 *   leaving the screen black for that whole time.
136	 *
137	 ****************************************************************************/
138	
139	static int sdmmc_mount_task(int argc, FAR char *argv[])
140	{
141	  int ret;
142	  int mount_retries;
143	  struct stat buf;
144	
145	  /* Create mount point for SD card */
146	
147	  ret = mkdir("/mnt", 0755);
148	  if (ret < 0 && errno != EEXIST)
149	    {
150	      syslog(LOG_ERR, "ERROR: Failed to create /mnt: %d\n", ret);
151	    }
152	
153	  ret = mkdir("/mnt/sd", 0755);
154	  if (ret < 0 && errno != EEXIST)
155	    {
156	      syslog(LOG_ERR, "ERROR: Failed to create /mnt/sd: %d\n", ret);
157	    }
158	
159	  /* SD initialize.
160	   * The TF card slot is wired for SPI (MOSI=GPIO1, SCK=GPIO2, MISO=GPIO3,
161	   * SDCS=GPIO17) but we use native SDMMC 1-bit mode.  The card samples its
162	   * CS/DAT3 line at power-on to decide between SPI and SD mode; drive GPIO17
163	   * high so the card enters SD mode and stays there after a soft reboot.
164	   */
165	
166	  esp32s3_configgpio(17, OUTPUT);
167	  esp32s3_gpiowrite(17, true);
168	  usleep(10000);
169	
170	  syslog(LOG_INFO, "Initializing SDMMC...\n");
171	  ret = board_sdmmc_initialize();
172	  if (ret < 0)
173	    {
174	      syslog(LOG_ERR, "ERROR: Failed to initialize SDMMC: %d\n", ret);
175	    }
176	  else
177	    {
178	      syslog(LOG_INFO, "SDMMC initialized successfully\n");
179	    }
180	
181	  /* Wait for SD card to be ready and try to mount with retries.
182	   * Some cards take longer to become ready after power-on, so we first
183	   * wait for the block device to appear and then retry the mount.
184	   */
185	
186	  syslog(LOG_INFO, "Waiting for SD card...\n");
187	
188	  for (mount_retries = 0; mount_retries < 20; mount_retries++)
189	    {
190	      if (stat("/dev/mmcsd1", &buf) == 0)
191	        {
192	          ret = nx_mount("/dev/mmcsd1", "/mnt/sd", "vfat", 0, NULL);
193	          if (ret == OK)
194	            {
195	              syslog(LOG_INFO, "SD card mounted at /mnt/sd\n");
196	              break;
197	            }
198	
199	          syslog(LOG_ERR, "ERROR: Failed to mount SD card (attempt %d): %d\n",
200	                 mount_retries + 1, ret);
201	        }
202	      else
203	        {
204	          syslog(LOG_INFO, "SD card block device not ready (attempt %d)\n",
205	                 mount_retries + 1);
206	        }
207	
208	      usleep(200000);  /* Wait 200ms before retry */
209	    }
210	
211	#ifdef CONFIG_SYSLOG_FILE
212	  /* After SD card mount, redirect syslog to a file on the SD card.
213	   * This keeps logs persistent across reboots and frees the USB console.
214	   * syslog_file_channel() internally handles log rotation, auto-reconnect
215	   * on card removal, and crash-safe flush via the interrupt buffer.
216	   */
217	
218	  ret = mkdir("/mnt/sd/syslog", 0755);
219	  if (ret < 0 && errno != EEXIST)
220	    {
221	      syslog(LOG_ERR, "ERROR: Failed to create syslog dir: %d\n", ret);
222	    }
