57	static bool syslog_safe_to_block(void)
58	{
59	#ifndef CONFIG_DISABLE_SIGNALS
60	  FAR const struct tcb_s *rtcb;
61	#endif
62	
63	  /* It's not safe to block in interrupts or when executing the idle loop */
64	
65	  if (up_interrupt_context() || sched_idletask())
66	    {
67	      return false;
68	    }
69	
70	  /* It's not safe to block if a signal is being delivered */
71	
72	#ifndef CONFIG_DISABLE_SIGNALS
73	  rtcb = nxsched_self();
74	  if (rtcb->sigdeliver != NULL)
75	    {
76	      return false;
77	    }
78	#endif
79	
80	  return true;
81	}
