87	/****************************************************************************
88	 * Name: syslog_write_foreach
89	 *
90	 * Description:
91	 *   This provides a default write method for syslog devices that do not
92	 *   support multiple byte writes  This functions simply loops, outputting
93	 *   one character at a time.
94	 *
95	 * Input Parameters:
96	 *   buffer - The buffer containing the data to be output
97	 *   buflen - The number of bytes in the buffer
98	 *
99	 * Returned Value:
100	 *   On success, the number of characters written is returned.  A negated
101	 *   errno value is returned on any failure.
102	 *
103	 ****************************************************************************/
104	
105	ssize_t syslog_write_foreach(FAR const char *buffer,
106	                             size_t buflen, bool force)
107	{
108	  syslog_write_t write;
109	  syslog_putc_t  putc;
110	  size_t nwritten = 0;
111	  ssize_t ret;
112	  int i;
113	
114	  for (i = 0; i < CONFIG_SYSLOG_MAX_CHANNELS; i++)
115	    {
116	      FAR syslog_channel_t *channel = g_syslog_channel[i];
117	
118	      if (channel == NULL)
119	        {
120	          break;
121	        }
122	
123	#ifdef CONFIG_SYSLOG_IOCTL
124	      if (channel->sc_state & SYSLOG_CHANNEL_DISABLE)
125	        {
126	          continue;
127	        }
128	#endif
129	
130	      write = !force ? channel->sc_ops->sc_write :
131	                       channel->sc_ops->sc_write_force;
132	      if (write != NULL)
133	        {
134	          nwritten = 0;
135	
136	#ifdef CONFIG_SYSLOG_CRLF
137	          if (!(channel->sc_state & SYSLOG_CHANNEL_DISABLE_CRLF))
138	            {
139	              size_t head;
140	
141	              for (head = 0; head < buflen; head++)
142	                {
143	                  if (buffer[head] != '\n')
144	                    {
145	                      continue;
146	                    }
147	
148	                  ret = write(channel, buffer + nwritten, head - nwritten);
149	                  if (ret >= 0)
150	                    {
151	                      ret = write(channel, "\r\n", 2);
152	                    }
153	
154	                  if (ret < 0)
155	                    {
156	                      return ret;
157	                    }
158	
159	                  nwritten = head + 1;
160	                }
161	            }
162	#endif
163	
164	          if (nwritten < buflen)
165	            {
166	              ret = write(channel, buffer + nwritten, buflen - nwritten);
167	              if (ret < 0)
168	                {
169	                  return ret;
170	                }
171	              else
172	                {
173	                  nwritten += ret;
174	                }
175	            }
176	        }
177	      else
178	        {
179	          putc = !force ? channel->sc_ops->sc_putc :
180	                          channel->sc_ops->sc_force;
181	          if (putc == NULL)
182	            {
183	              continue;
184	            }
185	
186	#ifdef CONFIG_SYSLOG_CRLF
187	          if (channel->sc_state & SYSLOG_CHANNEL_DISABLE_CRLF)
188	#endif
189	            {
190	              for (nwritten = 0; nwritten < buflen; nwritten++)
191	                {
192	                  putc(channel, buffer[nwritten]);
193	                }
194	            }
195	#ifdef CONFIG_SYSLOG_CRLF
196	          else
197	            {
198	              for (nwritten = 0; nwritten < buflen; nwritten++)
199	                {
200	                  if (buffer[nwritten] == '\n')
201	                    {
202	                      /* Add CR */
203	
204	                      putc(channel, '\r');
205	                    }
206	
207	                  putc(channel, buffer[nwritten]);
208	                }
209	            }
210	#endif
211	        }
212	    }
213	
214	  return nwritten;
215	}
