970	 ****************************************************************************/
971	
972	static ssize_t fat_write(FAR struct file *filep, FAR const char *buffer,
973	                         size_t buflen)
974	{
975	  FAR struct inode *inode;
976	  FAR struct fat_mountpt_s *fs;
977	  FAR struct fat_file_s *ff;
978	  unsigned int byteswritten;
979	  unsigned int writesize;
980	  FAR uint8_t *userbuffer = (FAR uint8_t *)buffer;
981	  int sectorindex;
982	  int ret;
983	
984	#ifndef CONFIG_FAT_FORCE_INDIRECT
985	  unsigned int nsectors;
986	  bool force_indirect = false;
987	#endif
988	
989	  DEBUGASSERT(filep->f_priv != NULL);
990	
991	  /* Recover our private data from the struct file instance */
992	
993	  ff = filep->f_priv;
994	
995	  /* Check for the forced mount condition */
996	
997	  if ((ff->ff_bflags & UMOUNT_FORCED) != 0)
998	    {
999	      return -EPIPE;
1000	    }
1001	
1002	  inode = filep->f_inode;
1003	  fs    = inode->i_private;
1004	
1005	  DEBUGASSERT(fs != NULL);
1006	
1007	  /* Make sure that the mount is still healthy */
1008	
1009	  ret = nxmutex_lock(&fs->fs_lock);
1010	  if (ret < 0)
1011	    {
1012	      return ret;
1013	    }
1014	
1015	  ret = fat_checkmount(fs);
1016	  if (ret != OK)
1017	    {
1018	      goto errout_with_lock;
1019	    }
1020	
1021	  /* Check if the file was opened for write access */
1022	
1023	  if ((ff->ff_oflags & O_WROK) == 0)
1024	    {
1025	      ret = -EACCES;
1026	      goto errout_with_lock;
1027	    }
1028	
1029	  /* Check if the file size would exceed the range of off_t */
1030	
1031	  if (buflen > OFF_MAX || ff->ff_size > OFF_MAX - (off_t)buflen)
1032	    {
1033	      ret = -EFBIG;
1034	      goto errout_with_lock;
1035	    }
1036	
1037	  /* Loop until either (1) all data has been transferred, or (2) an
1038	   * error occurs.  We assume we start with the current sector in
1039	   * cache (ff_currentsector)
1040	   */
1041	
1042	  byteswritten = 0;
1043	  sectorindex = filep->f_pos & SEC_NDXMASK(fs);
1044	
1045	  while (buflen > 0)
1046	    {
1047	      ret = fat_get_sectors(filep, false);
1048	      if (ret < 0)
1049	        {
1050	          goto errout_with_lock;
1051	        }
1052	
1053	#ifdef CONFIG_FAT_DIRECT_RETRY /* Warning avoidance */
1054	fat_write_restart:
1055	#endif
1056	
1057	#ifndef CONFIG_FAT_FORCE_INDIRECT
1058	      /* Check if the user has provided a buffer large enough to
1059	       * hold one or more complete sectors.
1060	       */
1061	
1062	      nsectors = buflen / fs->fs_hwsectorsize;
1063	      if (nsectors > 0 && sectorindex == 0 && !force_indirect)
1064	        {
1065	          /* Write maximum contiguous sectors directly from the user's
1066	           * buffer without using our tiny read buffer.
1067	           *
1068	           * Limit the number of sectors that we write on this time
1069	           * through the loop to the remaining contiguous sectors
1070	           * in this cluster
1071	           */
1072	
1073	          if (nsectors > ff->ff_sectorsincluster)
1074	            {
1075	              nsectors = ff->ff_sectorsincluster;
1076	            }
1077	
1078	          /* We are not sure of the state of the sector cache so the
1079	           * safest thing to do is write back any dirty, cached sector
1080	           * and invalidate the current cache content.
1081	           */
1082	
1083	          fat_ffcacheinvalidate(fs, ff);
1084	
1085	          /* Write all of the sectors directly from user memory */
1086	
1087	          ret = fat_hwwrite(fs, userbuffer, ff->ff_currentsector, nsectors);
1088	          if (ret < 0)

1088	          if (ret < 0)
1089	            {
1090	#ifdef CONFIG_FAT_DIRECT_RETRY
1091	              /* The low-level driver may return -EFAULT in the case where
1092	               * the transfer cannot be performed due to buffer memory
1093	               * constraints.  It is probable that the buffer is completely
1094	               * un-DMA-able or improperly aligned.  In this case, force
1095	               * indirect transfers via the sector buffer and restart the
1096	               * operation (unless we have already tried that).
1097	               */
1098	
1099	              if (ret == -EFAULT && !force_indirect)
1100	                {
1101	                  ferr("ERROR: DMA write alignment error,"
1102	                        " restarting indirect\n");
1103	                  force_indirect = true;
1104	                  goto fat_write_restart;
1105	                }
1106	#endif /* CONFIG_FAT_DIRECT_RETRY */
1107	
1108	              goto errout_with_lock;
1109	            }
1110	
1111	          ff->ff_sectorsincluster -= nsectors;
1112	          ff->ff_currentsector    += nsectors;
1113	          writesize                = nsectors * fs->fs_hwsectorsize;
1114	          ff->ff_bflags           |= FFBUFF_MODIFIED;
1115	        }
1116	      else
1117	#endif /* CONFIG_FAT_FORCE_INDIRECT */
1118	        {
1119	          /* Decide whether we are performing a read-modify-write
1120	           * operation, in which case we have to read the existing sector
1121	           * into the buffer first.
1122	           *
1123	           * There are two cases where we can avoid this read:
1124	           *
1125	           * - If we are performing a whole-sector write that was rejected
1126	           *   by fat_hwwrite(), i.e. sectorindex == 0 and buflen >= sector
1127	           *   size.
1128	           *
1129	           * - If the write is aligned to the beginning of the sector and
1130	           *   extends beyond the end of the file, i.e. sectorindex == 0 and
1131	           *   file pos + buflen >= file size.
1132	           */
1133	
1134	          if ((sectorindex == 0) && ((buflen >= fs->fs_hwsectorsize) ||
1135	              ((filep->f_pos + buflen) >= ff->ff_size)))
1136	            {
1137	              /* Flush unwritten data in the sector cache. */
1138	
1139	              ret = fat_ffcacheflush(fs, ff);
1140	              if (ret < 0)
1141	                {
1142	                  goto errout_with_lock;
1143	                }
1144	
1145	              /* Now mark the clean cache buffer as the current sector. */
1146	
1147	              ff->ff_cachesector = ff->ff_currentsector;
1148	            }
1149	          else
1150	            {
1151	              /* Read the current sector into memory (perhaps first flushing
1152	               * the old, dirty sector to disk).
1153	               */
1154	
1155	              ret = fat_ffcacheread(fs, ff, ff->ff_currentsector);
1156	              if (ret < 0)
1157	                {
1158	                  goto errout_with_lock;
1159	                }
1160	            }
1161	
1162	          /* Copy the requested part of the sector from the user buffer */
1163	
1164	          writesize = fs->fs_hwsectorsize - sectorindex;
1165	          if (writesize > buflen)
1166	            {
1167	              /* We will not write to the end of the buffer.  Set
1168	               * write size to the size of the user buffer.
1169	               */
1170	
1171	              writesize = buflen;
1172	            }
1173	          else
1174	            {
1175	              /* We will write to the end of the buffer (or beyond).  Bump
1176	               * up the current sector number (actually the next sector
1177	               * number).
1178	               */
1179	
1180	              ff->ff_sectorsincluster--;
1181	              ff->ff_currentsector++;
1182	            }
1183	
1184	          /* Copy the data into the cached sector and make sure that the
1185	           * cached sector is marked "dirty"
1186	           */
1187	
1188	          memcpy(&ff->ff_buffer[sectorindex], userbuffer, writesize);
1189	          ff->ff_bflags |= (FFBUFF_DIRTY | FFBUFF_VALID | FFBUFF_MODIFIED);
1190	        }
1191	
1192	      /* Set up for the next write */
1193	
1194	      userbuffer   += writesize;
1195	      filep->f_pos += writesize;
1196	      byteswritten += writesize;
1197	      buflen       -= writesize;
1198	      sectorindex   = filep->f_pos & SEC_NDXMASK(fs);
1199	
1200	      /* Update the file size */
1201	
1202	      if (filep->f_pos > ff->ff_size)
1203	        {
1204	          ff->ff_size = filep->f_pos;
1205	        }
1206	    }
1207

1206	    }
1207	
1208	  nxmutex_unlock(&fs->fs_lock);
1209	  return byteswritten;
1210	
1211	errout_with_lock:
1212	  nxmutex_unlock(&fs->fs_lock);
1213	  return ret;
1214	}
